import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long P = in.nextLong();
        long R = in.nextLong();
        long T = in.nextLong();

        long simple = P + (P * R / 100) * T;
        long compound = P;
        for (long i = 0; i < T; i++) {
            compound += compound * R / 100;
        }

        System.out.println(simple + " " + compound);
    }
}

solution.cpp:
#include <iostream>
using namespace std;

int main() {
    long long P, R, T;
    if (cin >> P >> R >> T) {
        long long simple = P + (P * R / 100) * T;
        long long compound = P;
        for (long long i = 0; i < T; i++) {
            compound += compound * R / 100;
        }
        cout << simple << " " << compound << endl;
    }
    return 0;
}
